        @tier "domain"
      valueStart : number = 37
        @label "Value Start"
        @tier "domain"
      setpointDefault : number = 37
        @label "Setpoint Default"
        @tier "domain"
      setpointMin : number = 30
        @label "Setpoint Min"
        @tier "domain"
      setpointMax : number = 44
        @label "Setpoint Max"
        @tier "domain"
      setpointStep : number = 0.5
        @label "Setpoint Step"
        @tier "presentation"
      rateDefault : number = 0.8
        @label "Rate Default"
        @tier "domain"
      rateMin : number = 0.05
        @label "Rate Min"
        @tier "domain"
      rateMax : number = 3
        @label "Rate Max"
        @tier "domain"
      rateStep : number = 0.05
        @label "Rate Step"
        @tier "presentation"
      shockSize : number = 4
